(()=>{const nav=document.querySelector('nav'),toggle=document.querySelector('.mobile-menu-toggle'),links=document.querySelector('.navlinks');function close(){nav.classList.remove('menu-open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','Open navigation')}toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';nav.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Close navigation':'Open navigation')});links.querySelectorAll('a').forEach(a=>a.addEventListener('click',close));document.addEventListener('click',e=>{if(!nav.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('menu-open')){close();toggle.focus()}});matchMedia('(min-width:801px)').addEventListener('change',close);document.querySelector('.navcta').addEventListener('click',close)})();
